// Minimal CDP WebSocket client for driving headless Chrome on file://
const http = require('http');
const net = require('net');
const { randomBytes } = require('crypto');
const { spawn, execFile } = require('child_process');

function wsConnect(wsUrl, onMessage, onError, onClose) {
  const u = new URL(wsUrl);
  const key = randomBytes(16).toString('base64');
  const req = http.request({
    hostname: u.hostname, port: u.port, path: u.pathname + u.search || '/',
    headers: {
      'Upgrade': 'websocket',
      'Connection': 'Upgrade',
      'Sec-WebSocket-Key': key,
      'Sec-WebSocket-Version': '13',
      'Host': u.host
    }
  }, (res) => {
    res.resume(); // switch to raw
    const socket = res.socket;
    let buf = Buffer.alloc(0);
    socket.setEncoding('binary');
    socket.on('data', (d) => {
      buf = Buffer.concat([buf, d]);
      while (buf.length >= 2) {
        const b0 = buf[0], b1 = buf[1];
        const fin = (b0 >> 7) & 1, op = b0 & 0x0f;
        const mask = (b1 >> 7) & 1;
        let off = 2, len;
        const l = b1 & 0x7f;
        if (l < 126) len = l;
        else if (l === 126) { len = buf.readUInt16BE(off); off += 2; }
        else if (l === 127) { len = buf.readBigUInt64BE(off, true); off += 8; len = len; }
        else { onError('bad len'); return; }
        if (off + len > buf.length) { buf = Buffer.alloc(0); return; } // incomplete, wait more
        const payload = buf.slice(off, off + len);
        off += len;
        if (!mask) {
          // unmasked
          if (op === 0x00) { /* close */ }
          else if (op === 1) {
            const msg = payload.toString('utf8');
            try { onMessage(JSON.parse(msg)); } catch (e) { onMessage(payload.toString('utf8')); }
          }
          off = 0;
          buf = buf.slice(off);
        } else {
          // not expected from server
          off = 0; buf = Buffer.alloc(0);
        }
      }
      buf = buf.length ? buf.slice(0, buf.length) : Buffer.alloc(0);
    });
    socket.on('close', () => { if (onClose) onClose(); });
    return socket;
  });
  req.on('error', (e) => { onError(e); });
  req.end();
}

// We need send capability; the wsConnect above returns socket but we also need to send.
// Re-do: return a send function.
function cdpClient(wsUrl) {
  const u = new URL(wsUrl);
  const key = randomBytes(16).toString('base64');
  const req = http.request({
    hostname: u.hostname, port: u.port, path: u.pathname + (u.search || ''),
    headers: {
      'Upgrade': 'websocket', 'Connection': 'Upgrade',
      'Sec-WebSocket-Key': key, 'Sec-WebSocket-Version': '13',
      'Host': u.host
    }
  }, (res) => {
    const socket = res.socket;
    res.resume();
    let buf = Buffer.alloc(0);
    let msgCounter = 0;
    const queue = [];
    let pending = null; // {id}

    function sendRaw(payload, opcode = 1, fin = 1) {
      // frame: 1-byte header, 2-byte header, 4 mask, payload
      let mask = randomBytes(4);
      const masked = Buffer.alloc(payload.length);
      for (let i = 0; i < payload.length; i++) masked[i] = payload[i] ^ mask[i];
      const len = masked.length;
      const header = Buffer.alloc(4);
      header[0] = (fin << 7) | opcode;
      header[1] = (0x80 << 7) | (len & 0x7f);
      let off = 2;
      if (len < 126) { header[1] = len; }
      else if (len < 65536) { header[1] = 0x80 | 126; header[off] = (len >> 8) & 0xff; header[++off] = len & 0xff; off = 4; }
      else { header[1] = 0x80 | 127; for (let i = 0; i < 8; i++) header[off++] = (len >> (8 * (7 - i))) & 0xff; }
