#!/usr/bin/env python3
# CDP driver for headless Chrome: load index.html, drive the UI, assert result.
import asyncio, json, subprocess, sys, time, re
from http.client import HTTPConnection
import websockets
import os

BASE = os.environ.get("BASE", "/home/dp/MyProjects/disc/.tmpwork/disc-pi-142bw98t/run")
URL = "file://" + os.path.join(BASE, "index.html")
PORT = 9232  # pick a free-ish port
LOG = open(os.path.join(BASE, "cdp_console.log"), "w", encoding="utf-8")

async def get_ws_url(port):
    for _ in range(60):
        try:
            r = HTTPConnection("127.0.0.1", port).
            c = HTTPConnection("127.0.0.1", port)
            c.request("GET", "/json")
            res = c.getresponse().read().decode()
            data = json.loads(res)
            return data[0]["wsUrl"]
        except Exception as e:
            time.sleep(0.15)
    raise RuntimeError("no page")

async def main():
    # start chrome
    proc = subprocess.Popen([
        "google-chrome-stable","--headless=new","--no-sandbox","--disable-gpu",
        "--remote-debugging-port=%d"%PORT,"--window-size=1200,900",
        "--disable-dev-shm-usage","--log-level=debug", URL],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    ws_url = await get_ws_url(PORT)

    errors = []
    async def on_msg(msg):
        t = msg.get("type")
        if t == "event" and msg.get("params",{}).get("method") == "Runtime.consoleAPICalled":
            p = msg["params"]["result"]
            severity = p.get("level", "info")
            text = p.get("message", "")
            errors.append(text) if severity in ("error",) else None
            print("[CONSOLE %s] %s" % (severity, text))

    ws = await websockets.connect(ws_url)
    msg_id = 1
    async def cdp(method, params=None):
        nonlocal msg_id
        req = {"id": msg_id, "method": method, "params": params or {}}
        msg_id += 1
        await ws.send(json.dumps(req))
        resp = await asyncio.wait_for(ws.recv(), 30)
        return json.loads(resp)

    await cdp("Page.enable")
    await cdp("Runtime.enable")
    await cdp("Log.enable")
    # subscribe to console
    try:
        await cdp("Runtime.consoleAPICalled")
    except Exception:
        pass

    # Let page load
    await asyncio.sleep(1.2)

    async def evaluate(expr):
        r = await cdp("Runtime.evaluate", {"expression": expr, "returnByValue": True})
        return r.get("result")

    # 1) Click open
    await evaluate("document.querySelector('.btn-open').click()")
    await asyncio.sleep(0.2)

    # 2) Verify modal open
    open_state = await evaluate("document.getElementById('wizardmodal').classList.contains('is-open')")
    print("modal open:", open_state)
    item_count = await evaluate("document.querySelectorAll('.disc-item').length")
    print("disc-items:", item_count)

    # 3) Drive to step 8 by clicking the Восьмой tab
    await evaluate("document.querySelectorAll('.disc-tab')[7].click()")
    await asyncio.sleep(0.2)
    finish_visible = await evaluate("!document.getElementById('btnFinish').hidden")
    next_visible = await evaluate("document.getElementById('btnNext').hidden")
    print("finish visible (should be true):", finish_visible)
    print("next hidden (should be true):", next_visible)

    # 4) REORDER to set a deterministic known scoring.
    #   Strategy: for each list, sort items so that a specific type is always top & bottom.
    #   We'll make a known pattern: in every list, put 'd' at top and 's' at bottom.
    #   Result: D +24, S -24, I 0, C 0. Dominant = D.
    await evaluate("""
    (function(){
      var lists = document.querySelectorAll('.disc-list');
      var expected = {};
      var d = {D:0,I:0,S:0,C:0};
      lists.forEach(function(ul){
        var lis = Array.from(ul.children);
        lis.forEach(function(li){
          var t = li.dataset.type.toUpperCase();
        });
      });
      // move 'd' to first, 's' to last in each list
      lists.forEach(function(ul){
        var lis = Array.from(ul.children);
        var top = lis.find(function(x){return x.dataset.type==='d';});
        var bot = lis.find(function(x){return x.dataset.type==='s';});
        if(top){ ul.insertBefore(top, ul.firstChild); }
        if(bot){ ul.insertBefore(bot, ul.lastChild); }
      });
      return Array.from(document.querySelectorAll('.disc-list')).map(function(ul){
        return Array.from(ul.children).map(function(li){return li.dataset.type;});
      });
    })()
    """)
    # compute expected by simulating the real collectPayload logic (mirrors code)
    result = await evaluate("""
    (function(){
      var d={D:0,I:0,S:0,C:0};
      var lists = document.querySelectorAll('.disc-list');
      lists.forEach(function(ul){
        var lis = Array.from(ul.children);
        lis.forEach(function(li,pos){
          var t = (li.dataset.type||'').toUpperCase();
          if(pos===0) d[t]=(d[t]||0)+1;
          else if(pos===3) d[t]=(d[t]||0)-1;
        });
      });
      return d;
    })()
    """)
    print("simulated scores (expected D24,S-24,I0,C0):", result)

    # 5) Click finish -> showResult
    await evaluate("document.getElementById('btnFinish').click()")
    await asyncio.sleep(0.3)

    # 6) Read result DOM
    score = await evaluate("document.getElementById('discResultScore').textContent")
    dom = await evaluate("document.getElementById('discResultDominant').textContent")
    types = await evaluate("""
      Array.from(document.querySelectorAll('.disc-type')).map(function(el){
        return {code: el.querySelector('.disc-type__code').textContent,
                value: el.querySelector('.disc-type__value').textContent,
                name: el.querySelector('.disc-type__name').textContent,
                dominant: el.classList.contains('is-dominant')};
      })
    """)
    hidden_result = await evaluate("document.getElementById('discResult').hidden")
    print("RESULT hidden:", hidden_result)
    print("SCORE:", repr(score))
    print("DOMINANT:", repr(dom))
    for tt in types:
        print("  type", tt)

    # Assert
    ok = True
    assert not hidden_result, "result should be visible"
    assert "D: 24" in score, "expected D: 24 in score, got %r" % score
    assert "S: -24" in score, "expected S: -24 in score"
    assert "D" in dom, "expected D dominant"
    tdict = {t['code']: t for t in types}
    assert tdict['D']['value'] == '24'
    assert tdict['S']['value'] == '-24'
    assert tdict['D']['dominant'], "D should be dominant"
    assert not any(t['dominant'] for t in types if t['code'] != 'D'), "only D dominant"
    print("ALL ASSERTIONS PASSED")

    await ws.close()
    proc.terminate()
    try: proc.wait(timeout=5)
    except: proc.kill()

if __name__ == "__main__":
    main()

